-- Estrutura e primeiros diagnósticos AWS com referências oficiais revisadas.
BEGIN;

CREATE TABLE IF NOT EXISTS aws_services (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS cost_scenarios (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_id BIGINT NOT NULL REFERENCES aws_services(id) ON DELETE CASCADE,
    slug TEXT NOT NULL,
    title TEXT NOT NULL,
    summary TEXT NOT NULL,
    is_published BOOLEAN NOT NULL DEFAULT TRUE,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (service_id, slug)
);

CREATE TABLE IF NOT EXISTS scenario_steps (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    scenario_id BIGINT NOT NULL REFERENCES cost_scenarios(id) ON DELETE CASCADE,
    step_type TEXT NOT NULL CHECK (step_type IN ('check', 'action', 'caution')),
    position SMALLINT NOT NULL CHECK (position > 0),
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    UNIQUE (scenario_id, step_type, position)
);

CREATE TABLE IF NOT EXISTS scenario_sources (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    scenario_id BIGINT NOT NULL REFERENCES cost_scenarios(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    url TEXT NOT NULL CHECK (
        url LIKE 'https://docs.aws.amazon.com/%'
        OR url LIKE 'https://aws.amazon.com/%'
    ),
    reviewed_at DATE NOT NULL DEFAULT CURRENT_DATE,
    UNIQUE (scenario_id, url)
);

CREATE TABLE IF NOT EXISTS feedback_entries (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category TEXT NOT NULL CHECK (category IN ('suggestion', 'issue', 'content')),
    message TEXT NOT NULL CHECK (char_length(btrim(message)) BETWEEN 10 AND 1000),
    submitted_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Guarda um HMAC por janela horária, nunca o endereço IP em texto claro.
CREATE TABLE IF NOT EXISTS feedback_rate_limits (
    address_hash CHAR(64) NOT NULL,
    window_start TIMESTAMPTZ NOT NULL,
    request_count INTEGER NOT NULL CHECK (request_count > 0),
    expires_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (address_hash, window_start)
);

CREATE INDEX IF NOT EXISTS cost_scenarios_published_idx
    ON cost_scenarios (service_id, slug)
    WHERE is_published = TRUE;
CREATE INDEX IF NOT EXISTS scenario_steps_order_idx
    ON scenario_steps (scenario_id, step_type, position);
CREATE INDEX IF NOT EXISTS scenario_sources_order_idx
    ON scenario_sources (scenario_id, title);
CREATE INDEX IF NOT EXISTS feedback_rate_limits_expiry_idx
    ON feedback_rate_limits (expires_at);

INSERT INTO aws_services (slug, name) VALUES
    ('amazon-eks', 'Amazon EKS'),
    ('amazon-dynamodb', 'Amazon DynamoDB'),
    ('amazon-rds', 'Amazon RDS'),
    ('amazon-s3', 'Amazon S3'),
    ('amazon-ebs', 'Amazon EBS'),
    ('nat-gateway', 'NAT Gateway'),
    ('aws-lambda', 'AWS Lambda')
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name;

INSERT INTO cost_scenarios (service_id, slug, title, summary)
SELECT service.id, scenario.slug, scenario.title, scenario.summary
FROM (VALUES
    ('amazon-eks', 'superdimensionamento-de-nos-do-cluster-node-over-provisioning',
        'Superdimensionamento de Nós do Cluster (Node Over-provisioning)',
        'Compare requests de CPU e memória com o uso observado antes de reduzir a capacidade do cluster.'),
    ('amazon-dynamodb', 'dimensionamento-de-capacidade-provisionada-sem-auto-scaling-provisioned-throughput',
        'Dimensionamento de Capacidade Provisionada sem Auto Scaling (Provisioned Throughput)',
        'Verifique o padrão de tráfego e throttling para decidir entre capacidade provisionada com Auto Scaling e modo sob demanda.'),
    ('amazon-rds', 'ambientes-de-desenvolvimento-e-homologacao-rodando-24-7',
        'Ambientes de Desenvolvimento e Homologação Rodando 24/7',
        'Confirme se instâncias não produtivas podem ser paradas em horários ociosos sem violar requisitos de disponibilidade ou recuperação.'),
    ('amazon-s3', 'manutencao-de-todos-os-arquivos-na-classe-s3-standard-24-7',
        'Manutenção de Todos os Arquivos na Classe S3 Standard 24/7',
        'Analise idade, frequência de acesso, tamanho e retenção dos objetos antes de criar regras de ciclo de vida.'),
    ('amazon-ebs', 'discos-ebs-orfaos-sem-instancia-conectada-unattached-volumes',
        'Discos EBS Órfãos sem Instância Conectada (Unattached Volumes)',
        'Identifique volumes sem instância anexada e confirme com as equipes se são necessários para recuperação ou auditoria.'),
    ('nat-gateway', 'trafego-para-s3-e-dynamodb-passando-pelo-nat-gateway',
        'Tráfego para S3 e DynamoDB Passando pelo NAT Gateway',
        'Use métricas e rotas para confirmar o tráfego e avaliar endpoints de gateway nas sub-redes que acessam esses serviços.'),
    ('aws-lambda', 'provisionamento-excessivo-de-memoria-ram-over-provisioning',
        'Provisionamento Excessivo de Memória RAM (Over-provisioning)',
        'Compare duração, memória máxima usada e erros em execuções representativas antes de alterar a configuração.')
) AS scenario(service_slug, slug, title, summary)
JOIN aws_services AS service ON service.slug = scenario.service_slug
ON CONFLICT (service_id, slug) DO UPDATE
SET title = EXCLUDED.title,
    summary = EXCLUDED.summary,
    updated_at = NOW();

INSERT INTO scenario_steps (scenario_id, step_type, position, title, content)
