INSERT INTO scenario_steps (scenario_id, step_type, position, title, content)
SELECT scenario.id, step.step_type, step.position, step.title, step.content
FROM (VALUES
    ('amazon-sns', 'falta-de-configuracao-de-dlq-para-entregas-http-s-de-webhooks', 'check', 1,
        'Verifique DLQs configuradas', 'Confirme se as assinaturas HTTP/HTTPS têm Dead Letter Queues configuradas para capturar falhas de entrega.'),
    ('amazon-sns', 'falta-de-configuracao-de-dlq-para-entregas-http-s-de-webhooks', 'check', 2,
        'Analise taxas de falha', 'Use métricas NumberOfNotificationsFailed e delivery status logs para identificar endpoints com falhas recorrentes.'),
    ('amazon-sns', 'falta-de-configuracao-de-dlq-para-entregas-http-s-de-webhooks', 'action', 1,
        'Configure DLQs para webhooks', 'Associe filas SQS como DLQ às assinaturas HTTP, definindo maxReceiveCount adequado para permitir retries antes do descarte.'),
    ('amazon-sns', 'falta-de-configuracao-de-dlq-para-entregas-http-s-de-webhooks', 'caution', 1,
        'DLQ sem monitoramento não resolve', 'Mensagens na DLQ precisam de processo de reprocessamento ou alerta; sem isso, a DLQ apenas acumula falhas.'),
    ('amazon-sns', 'falta-de-configuracao-de-dlq-para-entregas-http-s-de-webhooks', 'caution', 2,
        'Retries podem sobrecarregar parceiros', 'O SNS faz retries automáticos; se o parceiro está fora, retries repetidos geram tráfego e podem ser bloqueados. Avalie backoff adequado.')
) AS step(service_slug, scenario_slug, step_type, position, title, content)
JOIN aws_services AS service ON service.slug = step.service_slug
JOIN cost_scenarios AS scenario
    ON scenario.service_id = service.id AND scenario.slug = step.scenario_slug
ON CONFLICT (scenario_id, step_type, position) DO UPDATE
SET title = EXCLUDED.title,
    content = EXCLUDED.content;

