    ('amazon-emr', 'falta-de-migracao-para-efs-s3-emrfs',
        'Falta de Migração para EFS/S3 (EMRFS)',
        'Avalie uso de HDFS local quando EFS ou S3 via EMRFS seria mais adequado para armazenamento compartilhado.')
) AS scenario(service_slug, slug, title, summary)
