    ('amazon-emr', 'ausencia-de-alertas-no-aws-budgets-para-consumo-de-emr',
        'EMR pricing', 'https://aws.amazon.com/emr/pricing/'),
    ('amazon-emr', 'ausencia-de-alertas-no-aws-budgets-para-consumo-de-emr',
        'EMR overview', 'https://docs.aws.amazon.com/emr/latest/ManagementGuide/emr-what-is-emr.html')
) AS source(service_slug, scenario_slug, title, url)
JOIN aws_services AS service ON service.slug = source.service_slug
JOIN cost_scenarios AS scenario
    ON scenario.service_id = service.id AND scenario.slug = source.scenario_slug
ON CONFLICT (scenario_id, url) DO UPDATE
SET title = EXCLUDED.title,
    reviewed_at = CURRENT_DATE;

INSERT INTO cost_scenarios (service_id, slug, title, summary)
SELECT service.id, scenario.slug, scenario.title, scenario.summary
FROM (VALUES
    ('amazon-emr', 'leitura-de-arquivos-minusculos-small-files-problem',
        'Leitura de Arquivos Minúsculos (Small Files Problem)',
        'Avalie leitura de muitos arquivos pequenos no S3, onde o overhead de requests degrada performance e aumenta custos.')
) AS scenario(service_slug, slug, title, summary)
JOIN aws_services AS service ON service.slug = scenario.service_slug
ON CONFLICT (service_id, slug) DO UPDATE
SET title = EXCLUDED.title,
    summary = EXCLUDED.summary,
    updated_at = NOW();

INSERT INTO scenario_steps (scenario_id, step_type, position, title, content)
SELECT scenario.id, step.step_type, step.position, step.title, step.content
FROM (VALUES
    ('amazon-emr', 'leitura-de-arquivos-minusculos-small-files-problem', 'check', 1,
        'Analise tamanho de arquivos', 'Verifique se datasets têm muitos arquivos pequenos em vez de arquivos maiores.'),
    ('amazon-emr', 'leitura-de-arquivos-minusculos-small-files-problem', 'check', 2,
        'Identifique jobs lentos', 'Use logs para encontrar jobs que fazem muitas requests de leitura de arquivos pequenos.'),
    ('amazon-emr', 'leitura-de-arquivos-minusculos-small-files-problem', 'action', 1,
        'Compacte arquivos', 'Para datasets com muitos arquivos pequenos, consolide em arquivos maiores para reduzir requests.'),
    ('amazon-emr', 'leitura-de-arquivos-minusculos-small-files-problem', 'caution', 1,
        'Compactação requer processamento', 'Consolidar arquivos requer job de compactação; planeje para janela de baixa carga.'),
    ('amazon-emr', 'leitura-de-arquivos-minusculos-small-files-problem', 'caution', 2,
        'Arquivos muito grandes têm overhead', 'Se arquivos forem grandes demais, podem causar problemas de memória; encontre equilíbrio.')
) AS step(service_slug, scenario_slug, step_type, position, title, content)
JOIN aws_services AS service ON service.slug = step.service_slug
JOIN cost_scenarios AS scenario
    ON scenario.service_id = service.id AND scenario.slug = step.scenario_slug
ON CONFLICT (scenario_id, step_type, position) DO UPDATE
SET title = EXCLUDED.title,
    content = EXCLUDED.content;

