INSERT INTO scenario_steps (scenario_id, step_type, position, title, content)
SELECT scenario.id, step.step_type, step.position, step.title, step.content
FROM (VALUES
    ('amazon-neptune', 'uso-de-instancias-de-geracoes-antigas-ex-db-r4', 'check', 1,
        'Identifique gerações de instâncias', 'Liste instâncias Neptune e identifique gerações antigas como db.r4.'),
    ('amazon-neptune', 'uso-de-instancias-de-geracoes-antigas-ex-db-r4', 'check', 2,
        'Compare com gerações atuais', 'Determine se gerações mais novas estão disponíveis e se oferecem melhor custo-benefício.'),
    ('amazon-neptune', 'uso-de-instancias-de-geracoes-antigas-ex-db-r4', 'action', 1,
        'Migre para gerações novas', 'Para instâncias de gerações antigas, planeje migração para gerações mais novas que oferecem melhor performance.'),
    ('amazon-neptune', 'uso-de-instancias-de-geracoes-antigas-ex-db-r4', 'caution', 1,
        'Migração pode ter downtime', 'Migrar instâncias pode causar downtime; planeje janela de manutenção.'),
    ('amazon-neptune', 'uso-de-instancias-de-geracoes-antigas-ex-db-r4', 'caution', 2,
        'Gerações antigas podem ser descontinuadas', 'AWS pode descontinuar gerações antigas; migração é recomendada para evitar problemas futuros.')
) AS step(service_slug, scenario_slug, step_type, position, title, content)
JOIN aws_services AS service ON service.slug = step.service_slug
JOIN cost_scenarios AS scenario
    ON scenario.service_id = service.id AND scenario.slug = step.scenario_slug
ON CONFLICT (scenario_id, step_type, position) DO UPDATE
SET title = EXCLUDED.title,
    content = EXCLUDED.content;

